{"file_path":"safety_evals/loader.py","content":""""Load transcript logs and prepare transcript counts."""


def parse_transcript_log(lines):
    """Parse safety-monitor log lines into transcript dictionaries.

    Blank lines and comment lines are ignored. Malformed records raise
    ``ValueError`` with the original 1-based input line number.
    """
    out = []
    for line_number, line in enumerate(lines, start=1):
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue

        fields = [field.strip() for field in line.split(",")]
        if len(fields) != 3:
            raise ValueError(f"line {line_number}: expected exactly three fields")

        id_, day_text, flag_text = fields
        try:
            day = int(day_text)
        except ValueError as error:
            raise ValueError(f"line {line_number}: day must be an integer") from error

        if flag_text == "1":
            flagged = True
        elif flag_text == "0":
            flagged = False
        elif flag_text == "":
            flagged = None
        else:
            raise ValueError(f"line {line_number}: flagged must be 1, 0, or empty")

        out.append({"id": id_, "day": day, "flagged": flagged})
    return out


def dedupe_transcripts(events):
    """Keep each id's last transcript and sort by day, then id."""
    latest_by_id = {}
    for event in events:
        latest_by_id[event["id"]] = event
    return sorted(latest_by_id.values(), key=lambda event: (event["day"], event["id"]))


def daily_flag_counts(events, start_day, end_day):
    """Count flagged transcripts for each day in the inclusive range."""
    if end_day < start_day:
        return []

    counts = {day: 0 for day in range(start_day, end_day + 1)}
    for event in events:
        day = event["day"]
        if start_day <= day <= end_day and event["flagged"] is True:
            counts[day] += 1
    return [counts[day] for day in range(start_day, end_day + 1)]
