{"file_path":"tests/test_metrics.py","content":"import pytest

from safety_evals.loader import (
    daily_flag_counts,
    dedupe_transcripts,
    parse_transcript_log,
)
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_flag_rate_basic():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": False}]) == 0.5


def test_monitor_flag_rate_none_is_not_flagged():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": None}]) == 0.5
    assert monitor_flag_rate([]) == 0.0


def test_pooled_flag_rate_weights_each_transcript_equally():
    groups = {
        "large": [{"flagged": True}] + [{"flagged": False}] * 9,
        "small": [{"flagged": True}],
        "empty": [],
    }
    assert pooled_flag_rate(groups) == 2 / 11
    assert pooled_flag_rate({"empty": []}) == 0.0


def test_flags_in_window_uses_last_days_entries():
    assert flags_in_window([1, 2, 3, 4], 2) == 7
    assert flags_in_window([1, 2], 4) == 3
    assert flags_in_window([1, 2], 0) == 0


def test_parse_transcript_log_field_values_and_skipped_lines():
    assert parse_transcript_log([
        "  # comment",
        "  ",
        " x1 , 3 , 1 ",
        "x2,4,0",
        "x3,5,",
    ]) == [
        {"id": "x1", "day": 3, "flagged": True},
        {"id": "x2", "day": 4, "flagged": False},
        {"id": "x3", "day": 5, "flagged": None},
    ]


@pytest.mark.parametrize("line", ["x,not-a-day,1", "x,1", "x,1,1,extra"])
def test_parse_transcript_log_invalid_lines_report_line_number(line):
    with pytest.raises(ValueError, match="line 2"):
        parse_transcript_log(["# comment", line])


def test_dedupe_keeps_last_record_for_duplicate_id_and_sorts():
    events = [
        {"id": "a", "day": 5, "flagged": True},
        {"id": "b", "day": 2, "flagged": False},
        {"id": "a", "day": 1, "flagged": False},
    ]
    assert dedupe_transcripts(events) == [events[2], events[1]]


def test_daily_flag_counts_inclusive_range():
    events = [
        {"id": "a", "day": 1, "flagged": True},
        {"id": "b", "day": 2, "flagged": True},
        {"id": "c", "day": 2, "flagged": None},
        {"id": "d", "day": 5, "flagged": True},
    ]
    assert daily_flag_counts(events, 2, 4) == [1, 0, 0]
    assert daily_flag_counts(events, 4, 2) == []


def test_monitor_summary_matches_spec():
    groups = {
        "nonempty": [
            {"id": "a", "day": 1, "flagged": True},
            {"id": "b", "day": 2, "flagged": False},
            {"id": "c", "day": 3, "flagged": True},
        ],
        "empty": [],
    }
    assert monitor_summary(groups, 2) == {"rate": 0.667, "recent": 1, "groups": 1}
    assert monitor_summary({"empty": []}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_flagged_groups_and_group_rates():
    groups = {
        "z": [{"flagged": True}],
        "a": [{"flagged": True}],
        "empty": [],
        "b": [{"flagged": True}, {"flagged": False}],
    }
    assert top_flagged_groups(groups, 3) == ["a", "z", "b"]
    assert flag_rate_by_group(groups) == {"a": 1.0, "b": 0.5, "empty": None, "z": 1.0}


def test_longest_flag_streak():
    assert longest_flag_streak([1, 2, 0, 3, -1, 4]) == 2
    assert longest_flag_streak([]) == 0
